import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, useLocation } from 'react-router-dom';
import { bookingAPI, reviewAPI, roomAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';

const CreateReview = () => {
  const { roomId } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const { user } = useAuth();
  
  const [room, setRoom] = useState(null);
  const [booking, setBooking] = useState(null);
  const [reviewData, setReviewData] = useState({
    booking_id: '',
    rating: 5,
    comment: ''
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    if (!user) {
      navigate('/login');
      return;
    }
    
    fetchData();
  }, [roomId, user, navigate]);

  const fetchData = async () => {
    try {
      // Récupérer la salle
      const roomResponse = await roomAPI.getById(roomId);
      setRoom(roomResponse.data.room);
      
      // Récupérer les réservations terminées de l'utilisateur pour cette salle
      const bookingsResponse = await bookingAPI.getMyBookings();
      const completedBookings = bookingsResponse.data.bookings?.filter(
        b => b.room_id === parseInt(roomId) && b.status === 'completed'
      ) || [];
      
      if (completedBookings.length === 0) {
        setError('Vous n\'avez pas de réservation terminée pour cette salle.');
      } else {
        // Prendre la dernière réservation terminée
        const lastBooking = completedBookings[0];
        setBooking(lastBooking);
        setReviewData(prev => ({ ...prev, booking_id: lastBooking.id }));
      }
    } catch (error) {
      console.error('Erreur:', error);
      setError('Impossible de charger les données.');
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e) => {
    setReviewData({
      ...reviewData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSubmitting(true);

    try {
      const response = await reviewAPI.create(reviewData);
      
      if (response.success) {
        alert('Avis publié avec succès !');
        navigate(`/rooms/${roomId}`);
      }
    } catch (error) {
      setError(error.message || 'Erreur lors de la publication de l\'avis');
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="main-content">
        <div className="card">
          <p>Chargement...</p>
        </div>
      </div>
    );
  }

  if (error && !booking) {
    return (
      <div className="main-content">
        <div className="card">
          <h2>Impossible de laisser un avis</h2>
          <p className="error-message">{error}</p>
          <button onClick={() => navigate(`/rooms/${roomId}`)} className="btn btn-primary">
            Retour à la salle
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="main-content">
      <div className="card">
        <h1>Laisser un avis</h1>
        <p>Pour: <strong>{room?.title}</strong></p>
        <p>Réservation #{booking?.id} - Terminée le {new Date(booking?.end_datetime).toLocaleDateString('fr-FR')}</p>
      </div>

      <div className="card">
        {error && (
          <div className="alert alert-error">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label className="form-label">Note (1 à 5 étoiles)</label>
            <div className="rating-stars">
              {[1, 2, 3, 4, 5].map(star => (
                <button
                  key={star}
                  type="button"
                  className={`star-btn ${reviewData.rating >= star ? 'active' : ''}`}
                  onClick={() => setReviewData({...reviewData, rating: star})}
                >
                  ★
                </button>
              ))}
            </div>
            <input
              type="hidden"
              name="rating"
              value={reviewData.rating}
              onChange={handleChange}
            />
          </div>

          <div className="form-group">
            <label className="form-label">Commentaire</label>
            <textarea
              name="comment"
              className="form-input"
              value={reviewData.comment}
              onChange={handleChange}
              rows="5"
              placeholder="Partagez votre expérience..."
              maxLength="500"
            />
            <small style={{ color: '#666' }}>
              {reviewData.comment.length}/500 caractères
            </small>
          </div>

          <div className="form-buttons">
            <button 
              type="submit" 
              className="btn btn-primary"
              disabled={submitting}
            >
              {submitting ? 'Publication...' : 'Publier l\'avis'}
            </button>
            <button 
              type="button" 
              className="btn btn-secondary"
              onClick={() => navigate(`/rooms/${roomId}`)}
            >
              Annuler
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

// Ajouter ces styles dans App.css
const styles = `
.rating-stars {
  display: flex;
  gap: 10px;
  margin: 10px 0;
}

.star-btn {
  background: none;
  border: none;
  font-size: 2rem;
  cursor: pointer;
  color: #ddd;
  transition: color 0.2s;
}

.star-btn.active {
  color: #ffc107;
}

.star-btn:hover {
  color: #ffc107;
}

.form-buttons {
  display: flex;
  gap: 10px;
  margin-top: 20px;
}
`;

// Ajouter les styles
const styleSheet = document.createElement("style");
styleSheet.textContent = styles;
document.head.appendChild(styleSheet);

export default CreateReview;
